CREATE OR REPLACE FUNCTION public.can_manage_club_booking_user(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'club') AND public.owns_coaching_user(p_user,public.current_app_user_id()); $$;
REVOKE ALL ON FUNCTION public.can_manage_club_booking_user(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_manage_club_booking_user(uuid) TO authenticated, service_role;
CREATE POLICY "Clubs manage own gym sections" ON public.booking_sections FOR ALL TO authenticated USING (coach_id=public.current_app_user_id() AND public.has_role(auth.uid(),'club') AND booking_type='gym_visit') WITH CHECK (coach_id=public.current_app_user_id() AND public.has_role(auth.uid(),'club') AND booking_type='gym_visit');
CREATE POLICY "Clubs manage own gym appointments" ON public.booking_sessions FOR ALL TO authenticated USING (coach_id=public.current_app_user_id() AND booking_type='gym_visit' AND public.can_manage_club_booking_user(user_id)) WITH CHECK (coach_id=public.current_app_user_id() AND booking_type='gym_visit' AND public.can_manage_club_booking_user(user_id));
CREATE OR REPLACE FUNCTION public.ensure_coach_booking_calendar(p_coach uuid) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT(public.has_role(auth.uid(),'admin') OR(p_coach=public.current_app_user_id() AND (public.has_role(auth.uid(),'coach') OR public.has_role(auth.uid(),'club')))) THEN RAISE EXCEPTION 'Not authorized'; END IF; SELECT id INTO result FROM public.booking_sections WHERE coach_id=p_coach AND booking_type='gym_visit' ORDER BY created_at LIMIT 1; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.get_coach_booking_availability(p_user uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=public AS $$ BEGIN IF NOT(auth.role()='service_role' OR p_user=public.current_app_user_id() OR public.can_manage_coaching_user(p_user) OR public.can_manage_club_booking_user(p_user)) THEN RAISE EXCEPTION 'Not authorized'; END IF; RETURN private.get_coach_booking_availability(p_user); END $$;
CREATE OR REPLACE FUNCTION public.enforce_coaching_calendar() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.booking_sections%ROWTYPE; assigned uuid; assigned_auth uuid; BEGIN
SELECT * INTO s FROM public.booking_sections WHERE id=NEW.section_id;
IF TG_OP='UPDATE' THEN IF NEW.user_id IS NOT DISTINCT FROM OLD.user_id AND NEW.section_id IS NOT DISTINCT FROM OLD.section_id AND NEW.booking_date IS NOT DISTINCT FROM OLD.booking_date AND NEW.booking_time IS NOT DISTINCT FROM OLD.booking_time AND NEW.booking_type IS NOT DISTINCT FROM OLD.booking_type THEN NEW.coach_id:=OLD.coach_id; RETURN NEW; END IF; END IF;
SELECT u.coach_id,c.auth_user_id INTO assigned,assigned_auth FROM public.app_users u LEFT JOIN public.app_users c ON c.id=u.coach_id WHERE u.id=NEW.user_id;
IF s.coach_id IS NOT NULL THEN
 IF assigned IS DISTINCT FROM s.coach_id OR s.booking_type IS DISTINCT FROM NEW.booking_type THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Μπορείς να κλείσεις μόνο στο ημερολόγιο του δικού σου coach'; END IF;
 IF COALESCE(auth.role(),'')<>'service_role' AND NOT public.has_role(auth.uid(),'admin') AND NEW.user_id IS DISTINCT FROM public.current_app_user_id() AND NOT(s.coach_id=public.current_app_user_id() AND (public.can_manage_coaching_user(NEW.user_id) OR (NEW.booking_type='gym_visit' AND public.can_manage_club_booking_user(NEW.user_id)))) THEN RAISE EXCEPTION 'Not authorized'; END IF;
ELSIF NEW.booking_type='gym_visit' AND assigned IS NOT NULL AND NOT public.has_role(assigned_auth,'admin') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Μπορείς να κλείσεις μόνο στο ημερολόγιο του δικού σου coach'; END IF;
IF NOT COALESCE(s.is_active,false) THEN RAISE EXCEPTION 'Calendar inactive'; END IF;
NEW.coach_id:=s.coach_id;
IF s.coach_id IS NOT NULL AND TG_TABLE_NAME='booking_sessions' AND NEW.status IN('pending','confirmed') THEN
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.section_id::text||NEW.booking_date::text||NEW.booking_time::text,0));
 IF(SELECT count(*) FROM public.booking_sessions b WHERE b.section_id=NEW.section_id AND b.booking_date=NEW.booking_date AND b.booking_time=NEW.booking_time AND b.status IN('pending','confirmed') AND b.id<>NEW.id)>=s.max_capacity THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Η ώρα έχει ήδη κρατηθεί'; END IF;
END IF; RETURN NEW; END $$;